<?php
require __DIR__.'/core.php';
$db->exec('ALTER TABLE jp_media ADD COLUMN width INT DEFAULT 1; ALTER TABLE jp_media ADD COLUMN height INT DEFAULT 1');
lq_query($db,'INSERT INTO jp_users (id,email) VALUES (?,?)',[999,'copy@osloskolen.no']);
$original=lq_save($db,1,['content'=>['title'=>'Original quiz','scoring'=>'speed','questions'=>[$withImage,$withImage]]]);
$key=lq_share($db,1,$original['id'],true)['key'];
$before=lq_quiz($db,1,$original['id']);
rejects(fn()=>lq_copy_quiz($db,0,$original['id'],'public'),'anonymous cannot save copy');
$copy=lq_copy_quiz($db,999,$original['id'],'public');$row=lq_quiz($db,999,$copy['id']);$content=json_decode($row['content'],true);
check($copy['id']!==$original['id'] && $copy['revision']===1,'copy has independent id and revision');
check($content['title']==='Original quiz (kopi)' && $content['scoring']==='speed','title and scoring copied');
check($content['questions'][0]['correct']===$withImage['correct'],'answer key copied');
check(!isset($content['_share']) && !$content['private'],'copy has public default and no share key');
$image=$content['questions'][0]['image']['id'];check($image!==$img && $image===$content['questions'][1]['image']['id'],'repeated image copied once');
check(jp_media($db,$image,999)['bytes']==='PNG','copy owns its image');rejects(fn()=>jp_media($db,$img,999),'source image remains owned by original author');
$content['questions'][0]['prompt']='Changed copy';lq_save($db,999,['id'=>$copy['id'],'revision'=>1,'content'=>$content]);
check(lq_quiz($db,1,$original['id'])===$before,'editing copy leaves source unchanged');
$shared=lq_copy_quiz($db,999,$original['id'],'shared',$key);check($shared['id']!==$copy['id'],'shared link creates another independent copy');
rejects(fn()=>lq_copy_quiz($db,999,$original['id'],'shared',str_repeat('f',64)),'invalid share key rejected');
lq_share($db,1,$original['id'],false);rejects(fn()=>lq_copy_quiz($db,999,$original['id'],'shared',$key),'revoked share cannot copy even when public');
$source=json_decode($before['content'],true);$source['private']=true;lq_save($db,1,['id'=>$original['id'],'revision'=>1,'content'=>$source]);
rejects(fn()=>lq_copy_quiz($db,999,$original['id'],'public'),'private source cannot be copied');
check(lq_quiz($db,999,$copy['id'])['id']===$copy['id'],'existing copy survives source privacy change');
lq_delete($db,1,['id'=>$original['id']]);check(jp_media($db,$image,999)['bytes']==='PNG','copy image survives source deletion');
$quotaSource=lq_save($db,1,['content'=>['title'=>'Quota fixture','questions'=>[$withImage]]]);
lq_query($db,'INSERT INTO jp_media (id,owner_id,mime,size,width,height,bytes) VALUES (?,?,?,?,?,?,?)',[str_repeat('9',32),999,'image/png',50*1024*1024,1,1,'x']);
$count=(int)$db->query('SELECT COUNT(*) FROM lq_quizzes')->fetchColumn();$mediaCount=(int)$db->query('SELECT COUNT(*) FROM jp_media')->fetchColumn();
rejects(fn()=>lq_copy_quiz($db,999,$quotaSource['id'],'public'),'copy respects upload quota');
check($count===(int)$db->query('SELECT COUNT(*) FROM lq_quizzes')->fetchColumn() && $mediaCount===(int)$db->query('SELECT COUNT(*) FROM jp_media')->fetchColumn(),'failed copy leaves no quiz or media behind');
$own=lq_copy_quiz($db,1,$quotaSource['id'],'public');check(json_decode(lq_quiz($db,1,$own['id'])['content'],true)['questions'][0]['image']['id']===$img,'same owner reuses image');
echo "$checks checks including editable copies passed\n";
